def _get_obs(self):
    if self.with_velocity:
        obs = np.array(
            tuple(self.agent.position)
            + tuple(self.block.position)
            + (self.block.angle % (2 * np.pi),)
            + tuple(self.agent.velocity)
        ).astype(np.float32)
    else:
        obs = np.array(
            tuple(self.agent.position) + tuple(self.block.position) + (self.block.angle % (2 * np.pi),)
        ).astype(np.float32)
    return obs

